package mcjty.incontrol.rules.support;

public enum SpawnWhen {
    POSITION,
    ONJOIN,
    FINALIZE,
    DESPAWN;


    public static SpawnWhen getByName(String name) {
        for (SpawnWhen when : SpawnWhen.values()) {
            if (!when.name().equalsIgnoreCase(name)) continue;
            return when;
        }
        return null;
    }
}

